export function getEyeSvgContent(eyeId, eyeColor = "#8C501D") {
  const eye = SVG_EYES.find(e => e.id === eyeId) || SVG_EYES[0];
  let svg = eye.svgContent;
  svg = svg.replace(/rgb\(140,80,29\)/g, eyeColor);
  return svg;
}

export function getMouthSvgContent(mouthId) {
  const m = SVG_MOUTHS.find(x => x.id === mouthId) || SVG_MOUTHS[0];
  return m.svgContent;
}

export function getNoseSvgContent(noseId) {
  const n = SVG_NOSES.find(x => x.id === noseId) || SVG_NOSES[0];
  return n.svgContent;
}

export function getBlushSvgContent(blushId) {
  if (!blushId || blushId === "none") {
    return `<svg viewBox="0 0 145 21" class="cc-preview-icon"><circle cx="72.5" cy="10.5" r="8" fill="none" stroke="#c4b89e" stroke-width="2"/><line x1="66" y1="4" x2="79" y2="17" stroke="#c4b89e" stroke-width="2"/></svg>`;
  }
  const b = SVG_BLUSHES.find(x => x.id === blushId) || SVG_BLUSHES[0];
  return b.svgContent;
}

